-- Class notes synopsis batch 17: Marshmallow through Narrow-Leaf Echinacea

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Marshmallow</strong> (the "master hydrator") is a <strong>demulcent</strong>, <strong>moistening</strong>, <strong>cooling</strong>, <strong>vulnerary</strong>, and <strong>tonic</strong> herb that soothes and protects mucous membranes throughout the body; sweet, mucilaginous, and rich in polysaccharides. For the <strong>GI tract</strong>: soothes and protects the gut mucosal lining for <strong>leaky gut</strong> (full reset ~6 months, listed alongside flax seeds), <strong>gastric ulcers</strong> (heals gastric mucosa), <strong>heartburn</strong>, hot/dry constipation, and the drying that comes with aging; first herb for digestive support in <strong>pregnancy</strong> (queasy, difficulty digesting proteins and fats); constipation and heartburn in pregnancy (soothes stomach acids coming up); for <strong>hypochlorhydria</strong> (demulcent first-line); upper GI excess alongside <a href="?herb=78"><strong>Licorice</strong></a> and Comfrey root; paired with <a href="?herb=167"><strong>Cinnamon</strong></a> for warmth (<strong>caution in severe constipation</strong>); EP (powdered, heaping tablespoon into applesauce) before every meal to seal tight junctions - especially before coffee. Blend with <a href="?herb=167"><strong>Cinnamon</strong></a> and <a href="?herb=20"><strong>Ashwagandha</strong></a> for gut inflammation; "Strengthen and Repair" formula with <a href="?herb=44"><strong>Yarrow</strong></a> and <a href="?herb=92"><strong>Slippery Elm</strong></a>; Colon Rescue (with <a href="?herb=92"><strong>Slippery Elm</strong></a>, <a href="?herb=85"><strong>Plantain</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>) for diarrhea; ulcer-healing formula with <a href="?herb=85"><strong>Plantain</strong></a> and <a href="?herb=70"><strong>Calendula</strong></a> - root form specifically. For the <strong>urinary system</strong>: demulcent for the mucosal lining, moves hot and sticky waste. For the <strong>respiratory system</strong>: antitussive for hot/dry cough (sharp, painful, unproductive); demulcent for <strong>asthma</strong> and <strong>emphysema</strong>; hot and dry lung alongside <a href="?herb=61"><strong>Mullein</strong></a> and <a href="?herb=54"><strong>Elecampane</strong></a>; add to <a href="?herb=104"><strong>Osha</strong></a> when patient needs mucous membrane protection. For <strong>sore throat</strong>: powder with water and honey, sit for an hour, taken from a small 4 oz jar every few hours. <strong>Cancer</strong> support: cooling overheated systems during chemotherapy; nourishing, cooling, and tissue-protective chemo support in tea; in anti-cancer formula 1 for cooling in early-stage cancer; immune support and nourishment during chemo. <strong>Perimenopause</strong>: demulcent for dryness, with <a href="?herb=167"><strong>Cinnamon</strong></a> for warmth. Hydration support during fevers alongside <a href="?herb=84"><strong>Chamomile</strong></a>; high desert dehydration remedy; teas for hydration with <a href="?herb=90"><strong>Linden</strong></a> and <a href="?herb=167"><strong>Cinnamon</strong></a>. For dry constitution with <a href="?herb=92"><strong>Slippery Elm</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=127"><strong>Cardamom</strong></a>; alterative for cold constitution (combine with Cinnamon or Cardamom). Vulnerary in wound wash. Bulk-building herb for <strong>childhood constipation</strong> and in bulk-building candy; marshmallow gruel recommended as a moist, cooling food. Lymph/immune deficiency innate immunity alongside <a href="?herb=225"><strong>Astragalus</strong></a>, <a href="?herb=23"><strong>Wild Indigo</strong></a>, <a href="?herb=99"><strong>Myrrh</strong></a>, <a href="?herb=26"><strong>Echinacea</strong></a>, <a href="?herb=570"><strong>Cypress</strong></a>. Companion to <a href="?herb=2629"><strong>Andrographis</strong></a> as a tissue moistener given its intensity. Marshmallow bark and flowers: grounding and uplifting for sleep and relaxation support. Cheeseweed (mallow family) is a good substitute - demulcent, edible, leaves not root. Daily Tea blend: 5p Marshmallow leaf, 4p <a href="?herb=61"><strong>Mullein</strong></a>, 3p <a href="?herb=90"><strong>Linden</strong></a>, 2p <a href="?herb=850"><strong>Rose</strong></a>, 1p <a href="?herb=167"><strong>Cinnamon</strong></a>. Steady Study morning tea alongside <a href="?herb=109"><strong>Rosemary</strong></a>, <a href="?herb=2229"><strong>Gotu Kola</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=178"><strong>Oat Straw</strong></a>, <a href="?herb=1572"><strong>Chrysanthemum</strong></a>, <a href="?herb=1548"><strong>Goji</strong></a>, and <a href="?herb=17"><strong>Schizandra</strong></a>. Sleep formula: 2P <a href="?herb=145"><strong>Valerian</strong></a>, 1P <a href="?herb=128"><strong>California Poppy</strong></a>, 1/2 <a href="?herb=73"><strong>Hawthorn</strong></a> leaf and flower, 1/2 <a href="?herb=13"><strong>Holy Basil</strong></a>, 1/2 Marshmallow, 1/2 <a href="?herb=167"><strong>Cinnamon</strong></a>. With <a href="?herb=2233"><strong>Hibiscus</strong></a> glycerite as a demulcent to balance its acidity. Add to <a href="?herb=115"><strong>Mugwort</strong></a> cold infusion to temper bitterness. Preparation: mucilage is damaged by heat - use cold infusion (fridge overnight) or room-temperature water extraction; too fluffy to percolate - use maceration; use low alcohol and add glycerine for tincture; leaves and flowers have less polysaccharides (may be sufficient in spring); glycerin is a better match than alcohol for polysaccharides; cold infusion has short shelf life. <strong>Contraindicated for constitutionally damp patients.</strong>$$
WHERE id = 45;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Meadowsweet</strong> is an <strong>anti-inflammatory</strong> and <strong>astringent</strong>; promotes healthy inflammation regulation for <strong>musculoskeletal discomfort</strong>, <strong>sprains</strong>, <strong>strains</strong>, <strong>headaches</strong>, and chronic internal conditions; pairs well with <a href="?herb=2461"><strong>Jamaican Dogwood</strong></a> as an anti-inflammatory to reduce sensation of pain; sometimes used for general body pain in <strong>PMOS</strong> alongside <a href="?herb=81"><strong>St. John's Wort</strong></a> and <a href="?herb=25"><strong>Black Cohosh</strong></a>. A <strong>GI anti-inflammatory</strong> and cooling GI tonic for <strong>hyperchlorhydria</strong> - always the upper GI. Astringent for tonifying tissues in <strong>diarrhea</strong> alongside <a href="?herb=155"><strong>Raspberry</strong></a> root, <a href="?herb=44"><strong>Yarrow</strong></a>, and the Fagaceae family.$$
WHERE id = 75;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Mexican Marigold</strong> (Tagetes lucida) is a "grandmother plant" embodying "healing the healer" - sat with as a class opening herb; primary medicinal use is <strong>digestive</strong>, taken as a tea or bath.$$
