UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Milk Thistle</strong> (Silybum marianum) is the most potent <strong>hepatoprotective</strong> herb; actions include <strong>galactagogue</strong>, <strong>anti-hepatotoxic</strong>, <strong>antisclerotic</strong>, <strong>choleretic</strong> (increases bile production), and <strong>cholagogue</strong> (promotes bile flow) - works on the full biliary system; an "anabolic cooler" for metabolic fat/protein dysregulation; cooling and moistening. Helps the liver process toxins from any source - especially chemicals, extended pharma use, and alcohol; protects kidneys; specific for <strong>hepatitis</strong>, <strong>cirrhosis</strong>, elevated <strong>bilirubin</strong>, <strong>jaundice</strong>, and chemical sensitivities; treats tenderness and enlarged liver; safe at higher doses, safe with other medications, taken 3-12 months. Dose for <strong>Amanita mushroom poisoning</strong>: 5g/day. Phase 1 liver detox - high in flavonoids; avoid alcohol preparations for liver support (prefer Thorn capsule extract or standardized 80% silymarin; 600mg/day capsules). Eliminates hormones, bile, and waste; aids metabolizing fats and processing hormones; metabolizes estrogen (used in <strong>vaginitis</strong> treatment). Alterative for accumulation with aging alongside <a href="?herb=122"><strong>Dandelion</strong></a> root, <a href="?herb=22"><strong>Burdock</strong></a>, <a href="?herb=37"><strong>Yellow Dock</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>; for elimination and detox hepatics alongside <a href="?herb=17"><strong>Schizandra</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, <a href="?herb=28"><strong>Cleavers</strong></a>, <a href="?herb=37"><strong>Yellow Dock</strong></a>. In primary absorption tincture for <strong>thyroid/Hashimoto's</strong>: <a href="?herb=13"><strong>Holy Basil</strong></a>, <a href="?herb=17"><strong>Schizandra</strong></a>, <a href="?herb=20"><strong>Ashwagandha</strong></a>, Milk Thistle, <a href="?herb=109"><strong>Rosemary</strong></a>. Liver deficiency (fatigue, poor digestion, hormonal imbalances, difficulty processing emotions) - stimulates liver metabolism (berberine plant); liver excess - cools the anabolic tendency. Hepatic for <strong>rheumatoid arthritis</strong> (key herb for waste elimination); key step in <strong>PMOS</strong> treatment; for <strong>psoriasis</strong> - "go straight for Milk Thistle when there is a liver support picture"; for complex skin conditions including <strong>dermatitis</strong> and <strong>eczema</strong>. Eclectic remedy for swelling of the <strong>pancreas</strong> (standardized extract or tincture). Both choleretic and cholagogue - stimulates detox, bile production, and bowel movement stimulant (doses 20-60 drops, prioritize 40-60 drops for complex accumulation with chemical exposure, long-term pharma use, alcohol). For complex accumulation: prioritize 40-50 drops. Dose: FE 20-40 drops 5x/day, tincture 1/2-1 tsp 4x/day (avoid alcohol prep with active liver disease); choice of dandelion tea vs. milk thistle extract: milk thistle extract for more serious or chronic cases. Preparation: only seeds directly influence liver tissues; must leach starches first before silymarin comes out - a very milky tincture is low potency; standardized fluid extract best for serious conditions; can be used as food - seeds ground over savory foods.$$
WHERE id = 206;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Motherwort</strong> is a <strong>bitter</strong>, <strong>sedative</strong>, <strong>anxiolytic</strong>, <strong>hypotensive nervine</strong>, <strong>cardiotonic</strong>, and <strong>circulatory stimulant</strong> rich in <strong>rosmarinic acid</strong>. Differential picture: "fried and frazzled with tendency toward palpitations and heart stress" - for <strong>hormonal-induced stress</strong>, <strong>spasmodic dysmenorrhea</strong> (sedative, antispasmodic; tincture 30-60 drops to 4x/day; infusion 2-4 oz), and <strong>menopause-induced insomnia</strong>. For heart and chest anxiety and tightness with <a href="?herb=73"><strong>Hawthorn</strong></a>; a nervine; ingredient in calming blend for <strong>hypertension</strong> alongside <a href="?herb=90"><strong>Linden</strong></a> and <a href="?herb=73"><strong>Hawthorn</strong></a> L+F. Rosmarinic acid: specific for <strong>hyperthyroidism</strong> - calms uptake of T3 into tissues; cooling to aggravated heat thyroid; metabolic cooler for thyroid alongside <a href="?herb=133"><strong>Bugleweed</strong></a>; more indicated for hyperthyroidism but no harm for hypothyroidism. <strong>Reduces palpitations</strong>, antispasmodic. Listed among Black Herbal herbs for cardiovascular support. Serves double duty in <strong>respiratory</strong> support: nervine for the emotional and stress dimension of breathing plus circulatory stimulant supporting blood flow and gas exchange; for <strong>asthma</strong> (cardiotonic and nervine) and <strong>emphysema</strong> (cardiotonic with <a href="?herb=73"><strong>Hawthorn</strong></a> and nervine); dosing 1-4 mL. Supportive to circulatory, thyroid, and nervous system function - use in relation to the menstrual cycle, heat, anger, and inflammation ("big bear hug"). For <strong>negative self-talk</strong> and emotional depletion; for grief alongside <strong>Mimosa</strong> and <a href="?herb=2653"><strong>Bleeding Heart</strong></a>. Cooling bitter for <strong>hypochlorhydria</strong>. Female reproductive deficiency: stimulates HPA axis. Alkaloidal plant - requires 5-10% vinegar when tincturing. <strong>Can exacerbate hypothyroidal issues; caution in hypothyroidism.</strong>$$
WHERE id = 131;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Mugwort</strong> (Artemisia vulgaris) is a <strong>medium-bitter</strong> herb that is both <strong>carminative</strong> and <strong>bitter</strong>; downward, grounding, drying, and clearing action. Stimulates digestion; cooling bitter for <strong>hypochlorhydria</strong>; stimulates bile secretion for <strong>liver excess</strong> without stimulating liver metabolism; in digestive oxymel. Cold infusion recommended (volatile oils group); add <a href="?herb=45"><strong>Marshmallow</strong></a>, <a href="?herb=84"><strong>Chamomile</strong></a>, or <a href="?herb=134"><strong>Lemon Balm</strong></a> to temper bitterness. An <strong>emmenagogue</strong> - promotes menstruation by slightly irritating the uterine lining; compared to <a href="?herb=44"><strong>Yarrow</strong></a> for stimulating menstruation; "a big mover" of big energy. Used topically as <strong>antispasmodic</strong>; added to skin oils for <strong>pH maintenance</strong> and <strong>antimicrobial</strong> benefit. Associated with dreams and intuition; pillow use for wild, lucid, vivid dreams; oil great for dreaming and meditation anointing oils; applied to womb area during menstruation. <strong>Severely contraindicated during pregnancy - a big mover of energy; contraindicated for a limpia (spiritual cleanse) when pregnant. EO/hydrosol: extreme caution - toxin, neuro-toxin; better to use Wormwood.</strong>$$
WHERE id = 115;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Mullein</strong> is a <strong>demulcent</strong>, <strong>relaxing expectorant</strong>, <strong>pulmonary tonic</strong>, <strong>antitussive</strong>, and <strong>moistening</strong> herb with distinct medicine in each part: root for the <strong>prostate</strong>; stem for <strong>back pain</strong> and <strong>disk disorders</strong>; leaf for the <strong>lungs</strong>; flowers preferred over leaves (leaf hairs are irritating when not well-strained) for nourishing and moistening lung tissues - and as oil infusion with <a href="?herb=21"><strong>Garlic</strong></a> for congestion-type <strong>ear infections</strong>; flower tincture as anodyne (pain reliever) for earaches. For <strong>asthma</strong> (demulcent, relaxing expectorant, pulmonary tonic), <strong>emphysema</strong>/COPD (pulmonary tonic and demulcent - "no miracle cure, but with consistent use there will be some improvement"), and hot/dry cough (antitussive, cooling and moistening); moistening and soothing for the lungs in tea - similar to thyme. Soothing, toning, and expectorating - the expectorant alternative to <a href="?herb=140"><strong>Wild Cherry Bark</strong></a> when a cough is productive rather than dry. In Deep Lung Formula for <strong>bronchitis</strong>: <a href="?herb=54"><strong>Elecampane</strong></a>, <a href="?herb=65"><strong>Angelica</strong></a>, <a href="?herb=590"><strong>Yerba Santa</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=73"><strong>Hawthorn</strong></a>, Mullein, <a href="?herb=309"><strong>Yerba Mansa</strong></a>, <a href="?herb=21"><strong>Garlic</strong></a>, <a href="?herb=104"><strong>Osha</strong></a>. Lung tonics alongside <a href="?herb=11"><strong>Reishi Mushroom</strong></a>, <a href="?herb=85"><strong>Plantain</strong></a>, <a href="?herb=9"><strong>Siberian Ginseng</strong></a>. Hot and Dry Lung alongside <a href="?herb=45"><strong>Marshmallow</strong></a> and <a href="?herb=54"><strong>Elecampane</strong></a>. Respiratory excess: cool overproduction alongside <a href="?herb=151"><strong>Horsetail</strong></a>, <a href="?herb=2231"><strong>Grindelia</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=140"><strong>Wild Cherry Bark</strong></a> - may be a thyroid picture (especially hyperventilation with stress). Traditional Black American herbalism: leaf for measles, malaria, and smallpox; combined with <a href="?herb=92"><strong>Slippery Elm</strong></a> for bitter and digestive support. <a href="?herb=172"><strong>Artichoke</strong></a> leaf and Mullein for liver and hydration. Daily Tea blend: 5p <a href="?herb=45"><strong>Marshmallow</strong></a> leaf, 4p Mullein, 3p <a href="?herb=90"><strong>Linden</strong></a>, 2p <a href="?herb=850"><strong>Rose</strong></a>, 1p <a href="?herb=167"><strong>Cinnamon</strong></a>. Demulcent group alongside <a href="?herb=45"><strong>Marshmallow</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, and <a href="?herb=49"><strong>Irish Moss</strong></a>. Element tastes: Earth sweet, lung acrid/pungent, kidney salty, liver sour; mullein individuals get dry. Mullein Flower Essence: a guiding torch when someone is stuck in the "underworld" - for deep depression. Stalk historically used as a torch. Too fluffy to percolate - use maceration. Alterative for accumulation with aging (uncertain role).$$
WHERE id = 61;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Mustard</strong> is a <strong>diaphoretic</strong> used as a bath to promote sweating; mustard powder, flour, and water poultice applied to the chest for <strong>pneumonia</strong>.$$
