UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Myrrh</strong> (Commiphora myrrha) is an <strong>antimicrobial</strong> (effective against gram positive and negative bacteria), <strong>antifungal</strong>, <strong>astringent</strong>, <strong>vulnerary</strong>, and <strong>immune stimulant</strong> - uniquely stimulates leukocytes and innate immune function. For <strong>cuts</strong>, open wounds, infected wounds, and animal bites: applied externally as tincture or liniment; in wound kit primary topicals alongside <a href="?herb=33"><strong>Oregon Grape</strong></a> root and <a href="?herb=32"><strong>Chaparral</strong></a>. For <strong>mouth ulcers</strong>, dental issues, extractions, and <strong>gingivitis</strong>. Antimicrobial and immune stimulant for complex skin conditions (<strong>dermatitis</strong>, <strong>eczema</strong>, <strong>psoriasis</strong>). With <a href="?herb=26"><strong>Echinacea</strong></a>: stimulates immune function while addressing waste accumulation; for immune support with aging and waste accumulation; lymph/immune deficiency innate immunity. Heals <strong>gastric mucosa</strong> (peptic ulcer). Very heating and <strong>anti-inflammatory</strong> for <strong>joint pain</strong> - use in low part of formula. In Thompson's Standard Protocol as restorative (with cherry pits). Cold damp diarrhea: use resins in small amount, 75-90% alcohol (Eclectic method). Prized resin historically for anointing. Preparation: oleoresin - both water and alcohol soluble; does not extract well in water alone; use alcohol or oil-based preparations; resin 1:5 70%.$$
WHERE id = 99;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Narrow-Leaf Echinacea</strong> (Echinacea angustifolia) is stronger than <a href="?herb=26"><strong>Echinacea</strong></a> purpurea.$$
